        pref = step((sx, sy), ((w - 1) // 2, (h - 1) // 2))
        moves = [pref] + [m for m in moves if m != pref]
    cur = observation.get("scores", [0, 0])
    ahead = 0
    try:
        ahead = cur[0] - cur[1]
    except:
        ahead = 0
    choice = (0, 0)
    score = None
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if nx < 0 or ny < 0 or nx >= w or ny >= h or (nx, ny) in blocked:
            continue
        s = 0
        if best is not None:
            s -= abs(best[0] - nx) + abs(best[1] - ny)
